-- Generated by build_sightseeing_spot_seed.py. Do not edit by hand.
-- Idempotent: inserts only missing spotCode values.
-- Location resolved by exact location_details.location name; unmatched or
-- ambiguous names insert nothing for that location.

INSERT INTO ob_sightseeing_spots (locationId, spotCode, spotName, permitRequired, isActive, sortOrder)
SELECT loc.LID, 'RUMTEK_MONASTERY', 'Rumtek Monastery', 0, 1, 10
FROM (SELECT MIN(LID) AS LID FROM location_details
      WHERE LOWER(TRIM(location)) IN ('gangtok')
      HAVING COUNT(*) = 1) loc
WHERE loc.LID IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM ob_sightseeing_spots s WHERE s.spotCode = 'RUMTEK_MONASTERY');

